// Extrai mensagens privadas de clientes e o grupo oficial de estoque.
// Imagem so entra no fluxo de estoque quando veio de um grupo; o backend valida o JID exato.
const root = $input.first().json;
const b = root.body || root || {};
const data = b.data || {};
const key = data.key || {};
const event = String(b.event || root.event || '').toLowerCase();
if (event && (event.includes('messages.update') || event.includes('message.ack') || event.includes('reaction'))) return [];
const rawMessageTimestamp = data.messageTimestamp;
const epochSeconds = (value) => {
  let parsed = null;
  if (typeof value === 'number' || typeof value === 'string') {
    parsed = Number(value);
  } else if (value && typeof value.low === 'number') {
    const low = value.low < 0 ? value.low + 4294967296 : value.low;
    parsed = Number(value.high || 0) * 4294967296 + low;
  }
  if (!Number.isFinite(parsed) || parsed <= 0) return null;
  return parsed > 100000000000 ? parsed / 1000 : parsed;
};
const messageTimestamp = epochSeconds(rawMessageTimestamp);
const messageAgeSeconds = messageTimestamp == null ? null : (Date.now() / 1000) - messageTimestamp;
const MAX_MESSAGE_AGE_SECONDS = 300;
const MAX_FUTURE_SKEW_SECONDS = 120;
// Fail-closed: replay, evento sem horário e relógio muito adiantado não entram no CRM/IA.
if (
  messageAgeSeconds == null
  || messageAgeSeconds > MAX_MESSAGE_AGE_SECONDS
  || messageAgeSeconds < -MAX_FUTURE_SKEW_SECONDS
) return [];
const jid = String(key.remoteJid || '').trim();
const jidAlt = String(key.remoteJidAlt || '').trim();
const instance = String(b.instance || '').trim();
if (!instance) return []; // multi-WA: só body.instance do webhook Evolution
const msg = data.message || {};
if (msg.reactionMessage) return [];
const fromMe = Boolean(key.fromMe);
const privado = jid.endsWith('@s.whatsapp.net') || jid.endsWith('@lid');
const ehGrupo = jid.endsWith('@g.us');
// Eco do bot no grupo nunca reentra (evita loop de menu). fromMe privado segue para registrar handoff humano.
if (!jid || (!privado && !ehGrupo) || (ehGrupo && fromMe)) return [];
const audio = msg.audioMessage || null;
// Áudio desativado por enquanto: não registra, não chama IA e não responde.
if (audio) return [];
const imagem = msg.imageMessage || null;
const ehImagem = Boolean(imagem) && !fromMe;
const ehImagemEstoque = ehImagem && ehGrupo;
const texto = msg.conversation || msg.extendedTextMessage?.text || (ehImagem ? String(imagem.caption || '') : '');
if (!texto && !ehImagemEstoque) return [];
const participantes = [key.participantAlt, key.participant, data.participant, data.sender]
  .map((value) => String(value || '').trim());
const participante = participantes.find((value) => value.endsWith('@s.whatsapp.net'))
  || participantes.find((value) => value.endsWith('@lid'))
  || '';
const jidTelefone = ehGrupo ? participante : (jidAlt.endsWith('@s.whatsapp.net') ? jidAlt : jid);
if (ehGrupo && !jidTelefone) return [];
const telefone = jidTelefone.endsWith('@lid') ? jidTelefone : jidTelefone.split('@')[0];
const destino = ehGrupo ? jid : (jid.endsWith('@lid') ? jid : jid.split('@')[0]);
const ctx = msg.extendedTextMessage?.contextInfo
  || msg.imageMessage?.contextInfo
  || data.contextInfo
  || {};
const ad = ctx.externalAdReply || ctx.externalAdReplyInfo || {};
const referral = data.referral || msg.referral || ctx.referral || {};
const pick = (...vals) => {
  for (const v of vals) {
    const s = (v == null ? '' : String(v)).trim();
    if (s) return s;
  }
  return null;
};
const ctwa_clid = pick(
  ctx.ctwaClid, ctx.ctwa_clid, ad.ctwaClid, ad.ctwa_clid,
  referral.ctwa_clid, referral.ctwaClid, data.ctwaClid, data.ctwa_clid
);
const meta_ad_id = pick(
  ad.sourceId, ad.advertisementId, ad.adId, ctx.sourceId,
  referral.source_id, referral.ad_id, data.sourceId
);
const meta_campaign_id = pick(
  ad.campaignId, ctx.campaignId, referral.campaign_id, data.campaignId
);
const meta_adset_id = pick(ad.adsetId, ctx.adsetId, referral.adset_id);
const ctwa_source_type = pick(
  ctx.conversionSource, ctx.entryPointConversionSource,
  ad.sourceType, referral.source_type, data.conversionSource
);
const anuncioTitulo = pick(ad.title, ad.headline, referral.title, referral.headline);
const anuncioDescricao = pick(ad.body, ad.description, ad.caption, referral.body, referral.description);
const veioDeAnuncio = Boolean(
  ctwa_clid || meta_ad_id || meta_campaign_id || meta_adset_id || ctwa_source_type
  || anuncioTitulo || anuncioDescricao || Object.keys(referral).length
);
return [{ json: {
  instance, remoteJid: jid, remoteJidAlt: jidAlt, telefone, destino, texto,
  ehGrupo, grupoJid: ehGrupo ? jid : null, ehImagem, ehImagemEstoque,
  imageMimeType: ehImagem ? String(imagem.mimetype || '') : null,
  imageCaption: ehImagem ? String(imagem.caption || '') : null,
  pushName: data.pushName || '', providerMessageId: String(key.id || ''),
  fromMe, messageTimestamp, messageAgeSeconds,
  ctwa_clid, meta_ad_id, meta_campaign_id, meta_adset_id, ctwa_source_type,
  veioDeAnuncio, anuncioTitulo, anuncioDescricao
} }];

const estado = $input.first().json || {};
const origem = $('Extrair1').first().json;
// fromMe e duplicata: para. bot_ativo false NAO para aqui — menu da equipe
// ainda precisa passar; o gate de salvos so deixa cliente se bot_ativo true.
if (origem.fromMe || estado.duplicada === true) return [];
const botAtivo = estado.bot_ativo !== false;
return [{ json: { ...origem, bot_ativo: botAtivo } }];

let chat = {};
try { chat = $('Normalizar isSaved Evolution1').first().json || {}; } catch (e) {}
let origem = $('Extrair1').first().json;
const rot = $input.first().json || {};
const acao = rot.acao;
let estadoMensagem = {};
try { estadoMensagem = $('Registrar mensagem e ler handoff1').first().json || {}; } catch (e) {}
origem = {
  ...origem,
  primeiraMensagem: estadoMensagem.primeira_mensagem === true,
  historicoRecente: String(estadoMensagem.historico_recente || ''),
};
// CPF capturado na conversa (texto do histórico é mascarado).
const cpfCliente = String(estadoMensagem.cpf_cliente || estadoMensagem.cpfCliente || '').replace(/\D/g, '');
if (cpfCliente.length === 11) {
  try {
    const st = $getWorkflowStaticData('global');
    st['cpf-cliente:' + String(origem.telefone || '').replace(/\D/g, '')] = cpfCliente;
  } catch (_) {}
  origem = { ...origem, cpfCliente };
}

// Handoff manda no bot: bot_ativo vem do registrar (ler handoff), NAO do Extrair1.
const botAtivo = estadoMensagem.bot_ativo !== false;

// Juiz unico de lead virgem (fail-open): silencio so com prova positiva.
// tem_saida = conversa ja teve resposta (bot/atendente) -> segue se bot_ativo.
// NAO usar primeira_mensagem===false como silencio: a 2a msg do lead (antes do bot
// responder) ja tem primeira_mensagem false e precisa continuar atendendo.
function atendeLeadVirgem() {
  if (!botAtivo) return false;
  if (origem.ehGrupo) return false;
  // tem_saida ANTES de isSaved/chatFound: apos a 1a resposta do bot a Evolution
  // costuma achar o chat e marcar isSaved=true; isso nao pode calar a 2a msg.
  if (estadoMensagem.tem_saida === true) return true; // conversa em andamento
  if (chat.isSaved === true) return false; // prova: agenda do celular (1o contato)
  if (chat.chatFound === true) return false; // historico pre-bot no WA (1o contato sem saida)
  return true; // virgem, multi-msg rapida, ou Evolution cega (isSaved null)
}

if (!acao) {
  return atendeLeadVirgem() ? [{ json: { ...origem, acao: 'cliente' } }] : [];
}
if (acao === 'cliente') {
  // Aplica a mesma tranca: backend pode mandar cliente (fail-open), gate confirma virgem/handoff.
  return atendeLeadVirgem() ? [{ json: { ...origem, acao } }] : [];
}
if (acao === 'cadastro') {
  return [{ json: { ...origem, acao } }];
}
if (acao === 'cadastro_controle' || acao === 'operacao_controle') {
  const resposta = String(rot.resposta || '').trim();
  if (!resposta) return [];
  return [{ json: { ...origem, acao, output: resposta } }];
}
return [];

